mapper.select:
SELECT 
FROM xxl_job_operation_log AS t


		AND t.operation_module = #{operationModule}


		AND t.operation_type = #{operationType}


		AND t.operator like CONCAT(CONCAT('%', #{operator}), '%')


		AND t.operation_time  >=  #{startTime}


		AND t.operation_time  <=  #{endTime}


		AND t.job_group = #{jobGroup}


ORDER BY operation_time DESC
LIMIT #{offset}, #{pagesize}

SELECT count(1)
FROM xxl_job_operation_log AS t


		AND t.operation_module = #{operationModule}


		AND t.operation_type = #{operationType}


		AND t.operator like CONCAT(CONCAT('%', #{operator}), '%')


		AND t.operation_time  >=  #{startTime}


		AND t.operation_time  <=  #{endTime}


		AND t.job_group = #{jobGroup}
